/**
 * @file src/pdfFonts.ts
 * @description Devanagari (Hindi) and Oriya (Odia) TrueType fonts, embedded
 * as base64 rather than read from a loose file on disk, so the questions
 * PDF export (server.ts) renders Hindi/Odia question text correctly in
 * production too -- not just in local dev. PDFKit's built-in standard fonts
 * (Helvetica etc.) only cover Latin text; without an embedded Unicode font,
 * Hindi/Odia characters render as garbled mojibake (confirmed against a
 * real export before this was added).
 *
 * Embedded inline instead of loaded via fs.readFileSync(path) at runtime:
 * this app already has one confirmed case (the SSE broadcast's in-memory
 * `clients` array -- see TODO.md) of something that worked flawlessly in
 * local dev (`npm run dev`, one persistent process with the full repo on
 * disk) but broke silently in production on Vercel's serverless functions,
 * where the deployed bundle's file layout isn't guaranteed to match the
 * source tree. Embedding the font bytes in the JS bundle itself removes
 * that whole class of "works locally, not in prod" risk for this feature.
 *
 * Source: Google's official Noto Sans Devanagari / Noto Sans Oriya
 * (OFL-1.1 licensed), the complete/unsplit Regular weight from
 * github.com/notofonts/NotoSansDevanagari and
 * github.com/notofonts/NotoSansOriya -- NOT the per-script-subset files
 * npm's @fontsource packages ship (those exclude Latin letters from the
 * Oriya subset and are also what triggered a fontkit glyph-table offset
 * crash when used as WOFF2 directly; these are plain unhinted TTF).
 */

export const NOTO_SANS_DEVANAGARI_BASE64 = '';

export const NOTO_SANS_ORIYA_BASE64 = '';
